def search(arr, target):
    left = 0
    right = len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

mid = (left + right) // 2
if arr[mid] < target:
    left = mid + 1

if arr[mid] == target:
    return mid
elif arr[mid] < target:
    left = mid + 1

def search(arr, target):
    for index, value in enumerate(arr):
        if value == target:
            return index
    return -1

for i in range(len(arr)):
    if arr[i] == target:
        return i

for index, value in enumerate(arr):
    if value == target:
        return index

for value in arr:
    if value == target:
        return True

for i, item in enumerate(arr):
    if item == target:
        return i

return next(
    (i for i, v in enumerate(arr) if v == target),
    -1,
)
